/* -- النظائر والكتلة الذرية كما في الكتاب (ص 113–115) -- */
S({id:'bkiso',name:'م النظائر والكتلة الذرية في الكتاب',build:function(el){
  BK(el,'المحطة · النظائر والكتلة الذرية ص 113–115','النظائر والكتلة الذرية: أمثلة الكتاب',
   '<div style="display:grid;grid-template-columns:1fr 1fr;gap:12px">'+
   '<div class="card" style="'+CS+'"><h3 style="margin:0 0 4px">صندوق الكلور في الجدول الدوري (الشكل 9)</h3>'+bimg('bk_cl',260)+'<p style="margin:0">Cl هو رمز عنصر الكلور. العدد الأعلى (17) هو <b class="gl">العدد الذري</b>؛ فكل ذرة كلور يوجد في نواتها 17 بروتونًا. والعدد الأسفل (35.453) هو الكتلة الذرية.</p></div>'+
   '<div class="card" style="'+CS+'"><h3 style="margin:0 0 4px">نظيرا الكلور</h3><p style="margin:0">عدد النيوترونات قد يتغير من ذرة لأخرى للعنصر نفسه؛ فبعض ذرات الكلور تحتوي <b>18 نيوترونًا</b>، وبعضها <b>20 نيوترونًا</b>. هذان النوعان هما <b class="gl">كلور−35</b> و<b class="gl">كلور−37</b>، ويُسمّيان نظيرَي الكلور.</p><p style="margin:6px 0 0">وتتمثل نظائر العناصر بالرموز: الرقم العلوي على يسار الرمز يشير إلى العدد الكتلي، والسفلي إلى العدد الذري، مثل نظائر الكربون:</p><p style="direction:ltr;text-align:center;font-size:30px;margin:4px 0">'+['12','13','14'].map(function(a){return '<span style="display:inline-flex;align-items:center;margin:0 12px"><span style="display:inline-flex;flex-direction:column;font-size:16px;line-height:1.1;text-align:right"><b class="gl">'+a+'</b><b class="cyt">6</b></span><b>C</b></span>'}).join('')+'</p></div>'+
   '<div class="card" style="'+CS+'"><h3 style="margin:0 0 4px">نظائر الهيدروجين الثلاثة (الشكل 10)</h3>'+bimg('bk_hiso',520)+'<p style="margin:0">لها أعداد كتل مختلفة 1 و2 و3: البروتيوم لا يحتوي على نيوترونات، والديتيريوم يحتوي نيوترونًا واحدًا، والتريتيوم نيوترونين. ويُعدّ <b>البروتيوم</b> أكثر نظائر الهيدروجين شيوعًا.</p></div>'+
   '<div class="card" style="'+CS+'"><h3 style="margin:0 0 4px">الكتلة الذرية للكلور (الشكل 11)</h3>'+bimg('bk_pie',200)+'<p style="margin:0">إذا كان لديك 1000 ذرة كلور فإن 758 ذرة منها كلور−35، وحوالي 242 ذرة كلور−37. ولحساب متوسط كتل نظائر الكلور نجمع حاصل ضرب كتلة كل نظير بنسبة وجوده:</p><p style="direction:ltr;text-align:center;font-size:19px;margin:4px 0"><b>34.97 × 0.758 + 36.97 × 0.242 = 35.45</b></p><p class="hint" style="margin:0">(تنبه إلى استخدام النسبة في الصورة العشرية في الحساب.) ووحدة الكتلة الذرية (و.ك.ذ) تساوي 1/12 من كتلة ذرة الكربون−12.</p></div></div><div id="bq1" style="margin-top:12px"></div>');
  E.mcq($('#bq1',el),{id:'l2-bk-cl37',goal:3,lvl:1,q:'كم نيوترونًا في نواة ذرة الكلور−37؟ (العدد الذري للكلور 17)',o:['17','18','20','37'],a:2,ex:'النيوترونات = 37 − 17 = 20.'});
  return {enter:function(){E.complete('bkiso')},reveal:RV(el)}}});

